<?php require_once __DIR__.'/config.php';auth();if($_SESSION['rol']==='docente'){http_response_code(403);exit('Acceso restringido');}if($_SERVER['REQUEST_METHOD']==='POST'){checkcsrf();$id=postint('id');$st=$conexion->prepare("UPDATE cv_visitas SET estado='Finalizada',hora_salida=NOW() WHERE id=? AND estado='Dentro'");$st->bind_param('i',$id);$st->execute();flash($st->affected_rows?'Salida registrada correctamente.':'La visita ya fue finalizada.');go('salida.php');}$rows=$conexion->query("SELECT v.id,t.nombre,v.motivo,v.hora_entrada FROM cv_visitas v JOIN cv_visitantes t ON t.id=v.visitante_id WHERE v.estado='Dentro' ORDER BY v.id DESC");header_ui('Registrar salida');?><div class="panel p-4"><div class="table-responsive"><table class="table"><thead><tr><th>Visitante</th><th>Motivo</th><th>Entrada</th><th>Acción</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['nombre'])?></td><td><?=h($r['motivo'])?></td><td><?=h($r['hora_entrada'])?></td><td><form method="post" onsubmit="return confirm('¿Registrar la salida?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h($r['id'])?>"><button class="btn btn-outline-primary btn-sm">Registrar salida</button></form></td></tr><?php endwhile;?></tbody></table></div></div><?php footer_ui();
